<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Template</title><link rel="stylesheet" href="assets/admin.css"></head><body><aside class="sidebar"><div class="logo">DW</div><nav><a href="index.php">Dashboard</a><a class="active" href="templates.php">Template</a><a href="new.php">Buat Undangan</a><a href="logout.php">Keluar</a></nav></aside><main class="app"><header><div><h1>Template Undangan</h1><p>File sumber bersifat read-only dari sisi admin.</p></div></header><?php foreach($groups as $group):?><section class="template-category"><div class="category-head"><h2><?=e($group['label'])?></h2><span><?=count($group['templates'])?> template</span></div><?php if($group['templates']):?><div class="template-grid"><?php foreach($group['templates'] as $key=>$t):?><article class="template-card"><div class="preview-frame"><iframe src="template_preview.php?template=<?=urlencode($key)?>" loading="lazy"></iframe></div><div class="template-info"><span><?=e($t['category'])?></span><h3><?=e($t['name'])?></h3><div><a class="btn" target="_blank" href="template_preview.php?template=<?=urlencode($key)?>">Preview</a><a class="btn primary" href="new.php?template=<?=urlencode($key)?>">Pakai Template</a></div></div></article><?php endforeach?></div><?php else:?><div class="panel empty">Template <?=e($group['label'])?> belum tersedia.</div><?php endif?></section><?php endforeach?></main></body></html>
